import os, requests

api_key = open(os.environ.get('GALAXY_API_KEY_FILE','/claude_home/.galaxy/api_key')).read().strip()

# Try to get the tool source (R script) through Galaxy API
url = 'https://usegalaxy.org/api/tools/toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy3/raw'
headers = {'x-api-key': api_key}
resp = requests.get(url, headers=headers)
print(f"Status: {resp.status_code}")
if resp.status_code == 200:
    text = resp.text
    # Find batch_factors related sections
    lines = text.split('\n')
    for i, line in enumerate(lines):
        if 'batch' in line.lower():
            start = max(0, i-2)
            end = min(len(lines), i+20)
            for j in range(start, end):
                print(f"{j}: {lines[j]}")
            print("---")
